SourceCode.Declaration:
/// <summary>
/// An expression used to retrieve the company image, that is used for reports.
/// </summary>
[TFMDescription("An expression used to retrieve the on hand inventory.")]
class MobExpressionsOnHandInventory extends TFMExpressions
{
}

Method.Source:
public str processExpressionCommon(Common _common)
{
    SysDictTable    sdt                 = new SysDictTable(_common.TableId);
    FieldId         itemIdFieldId       = sdt.fieldName2Id(extendedTypeStr(ItemId));
    FieldId         inventDimFieldId    = sdt.fieldName2Id(extendedTypeStr(InventDimId));
    ItemId          itemId              = _common.(itemIdFieldId);
    InventDimId     inventDimId         = _common.(inventDimFieldId);
    InventOnhand    inventOnhand;
    InventDim       inventDim = inventDim::find(inventDimId);
    SetEnumerator   sEnum = InventDim::dimStorageDimFieldSet().getEnumerator();
    InventDimParm   inventDimParm;

    inventDim.wMSLocationId ='';
    inventDim.LicensePlateId='';

    inventDimParm.initFromInventDim(inventDim);

    inventOnhand = InventOnhand::newParameters(itemId, inventDim, inventDimParm);
    return MobHelper::formatItemQty(inventOnhand.physicalInvent());
}
